const escapeHtml = (value: string) => value
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const linkify = (value: string) => escapeHtml(value).replace(
  /(https:\/\/[^\s<]+)/g,
  '<a href="$1" style="color:#1769e0;text-decoration:underline;text-decoration-color:rgba(23,105,224,.35);text-underline-offset:3px">$1</a>',
);

const paragraphs = (value: string) => value
  .trim()
  .split(/\n{2,}/)
  .map((paragraph) => `<p style="margin:0 0 18px">${linkify(paragraph).replaceAll('\n', '<br>')}</p>`)
  .join('');

