import { supabase, invokeFinanceWorkflow } from '../../lib/supabase';
import type { MailMessage } from './types';

export type MailCalendarCandidate = {
  title: string;
  description: string;
  startsAt: string;
  endsAt: string;
  location: string;
};

const cleanText = (value: unknown, fallback = '') => String(value || fallback).trim();

export const messageSenderEmail = (message: MailMessage) => {
  const match = String(message.sender || '').match(/<([^>]+)>/);
  return (match?.[1] || message.sender || '').trim().toLowerCase();
};

export const messageSenderName = (message: MailMessage) => {
  const value = String(message.sender || '').replace(/<[^>]+>/g, '').replace(/^['"]|['"]$/g, '').trim();
  return value || messageSenderEmail(message).split('@')[0] || 'Customer';
};

export const calendarCandidatesFromMessage = (message: MailMessage): MailCalendarCandidate[] => {
  return (message.ai_action_items || []).flatMap((raw) => {
    const startsValue = raw.starts_at || raw.start_at || raw.start || raw.deadline || raw.due_at;
    const starts = new Date(String(startsValue || ''));
    if (!startsValue || Number.isNaN(starts.getTime())) return [];
    const explicitEnd = new Date(String(raw.ends_at || raw.end_at || raw.end || ''));
    const ends = Number.isNaN(explicitEnd.getTime())
      ? new Date(starts.getTime() + 30 * 60 * 1000)
      : explicitEnd;
    if (ends <= starts) ends.setTime(starts.getTime() + 30 * 60 * 1000);
    const title = cleanText(raw.title || raw.task, message.subject || 'Email follow up').slice(0, 160);
    return [{
      title,
      description: cleanText(raw.description || raw.context, `Created from email: ${message.subject || '(No subject)'}`).slice(0, 2000),
      startsAt: starts.toISOString(),
      endsAt: ends.toISOString(),
      location: cleanText(raw.location).slice(0, 240),
    }];
  });
};

const fingerprintFor = async (messageId: string, candidate: MailCalendarCandidate) => {
  const bytes = new TextEncoder().encode(`${messageId}|${candidate.title}|${candidate.startsAt}|${candidate.endsAt}`);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
};

export const addMailCandidateToCalendar = async (
  userId: string,
  message: MailMessage,
  candidate: MailCalendarCandidate,
) => {
  const fingerprint = await fingerprintFor(message.id, candidate);
  const existing = await supabase
    .from('wersee_mail_calendar_links')
    .select('calendar_event_id')
    .eq('user_id', userId)
    .eq('inbound_email_id', message.id)
    .eq('action_fingerprint', fingerprint)
    .maybeSingle();
  if (existing.error) throw existing.error;
  if (existing.data) return { created: false, eventId: existing.data.calendar_event_id };

  let calendar = await supabase
    .from('workspace_calendars')
    .select('id')
    .eq('user_id', userId)
    .order('position', { ascending: true })
    .limit(1)
    .maybeSingle();
  if (calendar.error) throw calendar.error;
  if (!calendar.data) {
    const created = await supabase
      .from('workspace_calendars')
      .insert({ user_id: userId, name: 'Mail', color: '#3276f0', position: 0 })
      .select('id')
      .single();
    if (created.error?.code === '23505') {
      calendar = await supabase.from('workspace_calendars').select('id').eq('user_id', userId).order('position').limit(1).single();
    } else if (created.error) {
      throw created.error;
    } else {
      calendar = created;
    }
  }

  const event = await supabase.from('workspace_calendar_events').insert({
    user_id: userId,
    calendar_id: calendar.data!.id,
    title: candidate.title,
    description: `${candidate.description}\n\nSource: Wersee Mail conversation ${message.id}`,
    location: candidate.location,
    starts_at: candidate.startsAt,
    ends_at: candidate.endsAt,
    all_day: false,
    status: 'scheduled',
    priority: 'normal',
    recurrence_rule: 'none',
  }).select('id').single();
  if (event.error) throw event.error;

  const link = await supabase.from('wersee_mail_calendar_links').insert({
    user_id: userId,
    inbound_email_id: message.id,
    action_fingerprint: fingerprint,
    calendar_event_id: event.data.id,
  });
  if (link.error) {
    await supabase.from('workspace_calendar_events').delete().eq('id', event.data.id).eq('user_id', userId);
    if (link.error.code === '23505') return { created: false, eventId: null };
    throw link.error;
  }
  return { created: true, eventId: event.data.id };
};

export const createInvoiceFromMail = async (input: {
  inboundId: string;
  customerEmail: string;
  customerName: string;
  itemTitle: string;
  memo: string;
  amount: number;
  currency: string;
}) => invokeFinanceWorkflow<{
  invoice: { id: string; invoice_number: string };
  paymentUrl: string;
  alreadyExists: boolean;
}>('invoice-create-from-mail', { ...input, idempotencyKey: crypto.randomUUID() });

export const createMailShare = async (input: {
  ownerUserId: string;
  message: MailMessage;
  teamId?: string | null;
}) => {
  const row = await supabase.from('wersee_mail_shares').insert({
    owner_user_id: input.ownerUserId,
    team_id: input.teamId || null,
    inbound_email_id: input.message.id,
    subject: input.message.subject || '',
    sender: input.message.sender || '',
    recipients: input.message.recipients || [],
    text_body: input.message.text_body || '',
    received_at: input.message.received_at,
  }).select('id,share_token,expires_at').single();
  if (row.error) throw row.error;
  return row.data;
};
