import { Navigate, Route, Routes } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { MailLandingPage } from './landing/MailLandingPage';
import { MailAuthCallback } from './MailAuthCallback';
import { MailAuthStart } from './MailAuthStart';
import { WerseeMailApp } from './WerseeMailApp';
import { MailSharedMessagePage } from './MailSharedMessagePage';

export const isWerseeMailHost = (hostname = typeof window === 'undefined' ? '' : window.location.hostname) =>
  hostname.toLowerCase() === 'email.wersee.com'
  || hostname.toLowerCase() === 'mail.wersee.com'
  || hostname.toLowerCase() === 'email.wersee.localhost'
  || /^wersee-mail-bridge(?:-[a-z0-9-]+)?\.vercel\.app$/.test(hostname.toLowerCase());

export const ProtectedMailApp = () => {
  const { user } = useAuth();
  return user ? <WerseeMailApp /> : <Navigate to="/" replace state={{ openSignIn: true }} />;
};

export const MailSubdomainRoutes = () => {
  const { user } = useAuth();
  return (
    <Routes>
      <Route path="/" element={user ? <Navigate to="/app" replace /> : <MailLandingPage />} />
      <Route path="/app" element={<ProtectedMailApp />} />
      <Route path="/settings" element={<ProtectedMailApp />} />
      <Route path="/auth/callback" element={<MailAuthCallback />} />
      <Route path="/auth/start" element={user ? <Navigate to="/app" replace /> : <MailAuthStart />} />
      <Route path="/shared/:token" element={<MailSharedMessagePage />} />
      <Route path="*" element={<Navigate to={user ? '/app' : '/'} replace />} />
    </Routes>
  );
};
