export const senderName = (sender: string) => {
  const match = sender.match(/^\s*"?([^"<]+)"?\s*</);
  return (match?.[1] || sender.split('@')[0] || 'Unknown sender').trim();
};

export const senderEmail = (sender: string) => {
  const match = sender.match(/<([^>]+)>/);
  return (match?.[1] || sender).trim().toLowerCase();
};

export const initialsFor = (value: string) => senderName(value)
  .split(/\s+/)
  .slice(0, 2)
  .map((part) => part[0]?.toUpperCase())
  .join('') || 'W';

export const relativeMailTime = (value: string) => {
  const date = new Date(value);
  const now = new Date();
  const sameDay = date.toDateString() === now.toDateString();
  if (sameDay) return new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' }).format(date);
  if (date.getFullYear() === now.getFullYear()) {
    return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(date);
  }
  return new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' }).format(date);
};

export const plainTextFromHtml = (html: string) => {
  if (typeof window === 'undefined') return html.replace(/<[^>]+>/g, ' ');
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  return (parsed.body.textContent || '').replace(/\n{3,}/g, '\n\n').trim();
};

export const safeMailDocument = (html: string, allowRemoteImages: boolean) => {
  if (typeof window === 'undefined') return '';
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  parsed.querySelectorAll('script, iframe, frame, object, embed, form, input, button, meta, link, base, svg, math').forEach((node) => node.remove());
  parsed.querySelectorAll('*').forEach((node) => {
    [...node.attributes].forEach((attribute) => {
      const name = attribute.name.toLowerCase();
      const value = attribute.value.trim();
      if (name.startsWith('on') || name === 'srcdoc' || name === 'formaction') node.removeAttribute(attribute.name);
      if ((name === 'href' || name === 'action') && !/^(https?:|mailto:|#)/i.test(value)) node.removeAttribute(attribute.name);
      if (name === 'style' && /url\s*\(/i.test(value)) node.removeAttribute(attribute.name);
    });
  });
  parsed.querySelectorAll('a').forEach((anchor) => {
    anchor.setAttribute('target', '_blank');
    anchor.setAttribute('rel', 'noopener noreferrer nofollow');
  });
  parsed.querySelectorAll('img').forEach((image) => {
    const source = image.getAttribute('src') || '';
    image.removeAttribute('srcset');
    if (!allowRemoteImages && /^https?:/i.test(source)) {
      image.setAttribute('data-remote-image', source);
      image.removeAttribute('src');
      image.setAttribute('alt', image.getAttribute('alt') || 'Remote image blocked');
    }
  });
  const imagePolicy = allowRemoteImages ? 'https: data:' : 'data:';
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="color-scheme" content="light dark"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src ${imagePolicy}; style-src 'unsafe-inline'; font-src data:; base-uri 'none'; form-action 'none'"><style>html{color-scheme:light dark}body{margin:0;padding:2px 4px;font:15px/1.65 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#202124;background:transparent;overflow-wrap:anywhere}img{max-width:100%;height:auto}a{color:#6750ee}@media(prefers-color-scheme:dark){body{color:#ededf0}a{color:#9f8cff}}</style></head><body>${parsed.body.innerHTML}</body></html>`;
};
