import { useMemo, useState } from 'react';
import {
  ArrowLeft,
  ArrowRight,
  AtSign,
  Building2,
  Check,
  Eye,
  EyeOff,
  KeyRound,
  Link2,
  LoaderCircle,
  LockKeyhole,
  Mail,
  Server,
  ShieldCheck,
  Sparkles,
} from 'lucide-react';
import type { ConnectedMailAccount } from './types';

export type MailConnectionProvider = 'wersee' | 'gmail' | 'microsoft' | 'imap';

export type MailConnectionRequest = {
  provider: MailConnectionProvider;
  email: string;
  username?: string;
  password?: string;
  imapHost?: string;
  smtpHost?: string;
  imapPort?: number;
  smtpPort?: number;
};

export type MailConnectionOutcome = 'connected' | 'redirecting' | 'failed';

type ProviderDefinition = {
  provider: MailConnectionProvider;
  name: string;
  detail: string;
  action: string;
};

const providers: ProviderDefinition[] = [
  {
    provider: 'wersee',
    name: 'Wersee Mail',
    detail: 'Your verified Wersee mailbox',
    action: 'Connect Wersee mailbox',
  },
  {
    provider: 'gmail',
    name: 'Gmail',
    detail: 'Gmail or Google Workspace',
    action: 'Continue with Google',
  },
  {
    provider: 'microsoft',
    name: 'Outlook',
    detail: 'Outlook or Microsoft 365',
    action: 'Continue with Microsoft',
  },
  {
    provider: 'imap',
    name: 'Business mail',
    detail: 'Connect secure IMAP + SMTP',
    action: 'Verify business mailbox',
  },
];

const providerName = (provider: MailConnectionProvider) =>
  providers.find((item) => item.provider === provider)?.name || provider;

const ProviderMark = ({ provider }: { provider: MailConnectionProvider }) => {
  if (provider === 'wersee') return <span className="wm-provider-mark is-wersee" aria-hidden="true"><Mail /></span>;
  if (provider === 'gmail') return <span className="wm-provider-mark is-gmail" aria-hidden="true">G</span>;
  if (provider === 'microsoft') {
    return (
      <span className="wm-provider-mark is-microsoft" aria-hidden="true">
        <i /><i /><i /><i />
      </span>
    );
  }
  return <span className="wm-provider-mark is-imap" aria-hidden="true"><Building2 /></span>;
};

type MailProviderConnectProps = {
  accounts: ConnectedMailAccount[];
  connecting: boolean;
  defaultEmail: string;
  werseeEmails?: string[];
  variant?: 'setup' | 'settings';
  onConnect: (request: MailConnectionRequest) => Promise<MailConnectionOutcome>;
  onConnected?: () => void;
};

export const MailProviderConnect = ({
  accounts,
  connecting,
  defaultEmail,
  werseeEmails = [],
  variant = 'settings',
  onConnect,
  onConnected,
}: MailProviderConnectProps) => {
  const pendingAccount = useMemo(
    () => accounts.find((account) => account.status !== 'connected' && ['wersee', 'gmail', 'microsoft', 'imap'].includes(account.provider)),
    [accounts],
  );
  const initialProvider = (pendingAccount?.provider === 'wersee' || pendingAccount?.provider === 'microsoft' || pendingAccount?.provider === 'imap')
    ? pendingAccount.provider as MailConnectionProvider
    : 'gmail';
  const [provider, setProvider] = useState<MailConnectionProvider>(initialProvider);
  const [email, setEmail] = useState(pendingAccount?.email || defaultEmail);
  const [username, setUsername] = useState(pendingAccount?.email || defaultEmail);
  const [password, setPassword] = useState('');
  const [imapHost, setImapHost] = useState('');
  const [smtpHost, setSmtpHost] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const selectedProvider = providers.find((item) => item.provider === provider) || providers[0];

  const selectProvider = (nextProvider: MailConnectionProvider) => {
    setProvider(nextProvider);
    setFormError(null);
    if (nextProvider === 'imap' && !username) setUsername(email);
    if (nextProvider === 'wersee' && werseeEmails[0]) setEmail(werseeEmails[0]);
  };

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const normalizedEmail = email.trim().toLowerCase();
    if (!/^\S+@\S+\.\S+$/.test(normalizedEmail)) {
      setFormError('Enter a valid mailbox email address.');
      return;
    }
    if (provider === 'imap' && (!imapHost.trim() || !smtpHost.trim() || !password || !(username.trim() || normalizedEmail))) {
      setFormError('Add the IMAP server, SMTP server, username and app password.');
      return;
    }

    setFormError(null);
    const outcome = await onConnect({
      provider,
      email: normalizedEmail,
      ...(provider === 'imap' ? {
        username: username.trim() || normalizedEmail,
        password,
        imapHost: imapHost.trim().toLowerCase(),
        smtpHost: smtpHost.trim().toLowerCase(),
        imapPort: 993,
        smtpPort: 465,
      } : {}),
    });
    if (outcome === 'connected') {
      setPassword('');
      onConnected?.();
    }
  };

  return (
    <form className={`wm-provider-connect is-${variant}`} onSubmit={submit}>
      <div className="wm-provider-grid" role="radiogroup" aria-label="Choose an email provider">
        {providers.map((item) => (
          <button
            key={item.provider}
            type="button"
            role="radio"
            aria-checked={provider === item.provider}
            className={provider === item.provider ? 'is-selected' : ''}
            onClick={() => selectProvider(item.provider)}
          >
            <ProviderMark provider={item.provider} />
            <span><b>{item.name}</b><small>{item.detail}</small></span>
            <span className="wm-provider-check"><Check /></span>
          </button>
        ))}
      </div>

      <div className="wm-provider-fields">
        <div className="wm-provider-fields-heading">
          <span><ProviderMark provider={provider} /></span>
          <div><b>Connect {selectedProvider.name}</b><small>{provider === 'imap' ? 'Your credentials are sent only to the secure mail connection service.' : provider === 'wersee' ? 'Use a verified address that already belongs to your Wersee Workspace.' : 'Wersee never sees your provider password.'}</small></div>
        </div>

        <label className="wm-provider-field is-wide">
          <span>Email address</span>
          <span className="wm-provider-input"><AtSign />{provider === 'wersee' && werseeEmails.length ? <select value={email} onChange={(event) => setEmail(event.target.value)}>{werseeEmails.map((address) => <option key={address} value={address}>{address}</option>)}</select> : <input type="email" value={email} onChange={(event) => { setEmail(event.target.value); if (provider === 'imap' && (!username || username === defaultEmail)) setUsername(event.target.value); }} placeholder="you@company.com" autoComplete="email" />}</span>
          {provider === 'wersee' ? <small>{werseeEmails.length ? 'Choose one of your verified Wersee sending identities.' : 'Enter an address on a domain you verified in Wersee Workspace.'}</small> : null}
        </label>

        {provider === 'imap' ? (
          <div className="wm-business-fields">
            <label className="wm-provider-field">
              <span>IMAP server</span>
              <span className="wm-provider-input"><Server /><input value={imapHost} onChange={(event) => setImapHost(event.target.value)} placeholder="imap.company.com" autoCapitalize="none" spellCheck={false} /></span>
              <small>Secure port 993</small>
            </label>
            <label className="wm-provider-field">
              <span>SMTP server</span>
              <span className="wm-provider-input"><Mail /><input value={smtpHost} onChange={(event) => setSmtpHost(event.target.value)} placeholder="smtp.company.com" autoCapitalize="none" spellCheck={false} /></span>
              <small>Secure port 465</small>
            </label>
            <label className="wm-provider-field">
              <span>Username</span>
              <span className="wm-provider-input"><AtSign /><input value={username} onChange={(event) => setUsername(event.target.value)} placeholder="Usually your full email" autoComplete="username" /></span>
            </label>
            <label className="wm-provider-field">
              <span>App password</span>
              <span className="wm-provider-input"><KeyRound /><input type={showPassword ? 'text' : 'password'} value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Provider app password" autoComplete="new-password" /><button type="button" onClick={() => setShowPassword((value) => !value)} aria-label={showPassword ? 'Hide app password' : 'Show app password'}>{showPassword ? <EyeOff /> : <Eye />}</button></span>
              <small>Use an app password when your provider supports it</small>
            </label>
          </div>
        ) : null}

        {formError ? <p className="wm-provider-error" role="alert">{formError}</p> : null}

        <div className="wm-provider-security">
          <ShieldCheck />
          <span><b>Review before connection</b><small>{provider === 'imap' ? 'Wersee verifies both servers before saving the mailbox connection.' : provider === 'wersee' ? 'The selected identity stays connected to your Wersee account and can be removed later.' : 'You will approve access on the provider’s own secure page.'}</small></span>
        </div>

        <button className="wm-provider-submit" type="submit" disabled={connecting}>
          {connecting ? <LoaderCircle className="wm-spin" /> : provider === 'imap' ? <LockKeyhole /> : provider === 'wersee' ? <Mail /> : <Link2 />}
          <span>{connecting ? 'Opening secure connection…' : selectedProvider.action}</span>
          {connecting ? null : <ArrowRight />}
        </button>
      </div>
    </form>
  );
};

type MailAccountSetupProps = MailProviderConnectProps & {
  userName: string;
  onSkip: () => void;
  onToggleTheme: () => void;
  theme: 'light' | 'dark';
};

export const MailAccountSetup = ({
  accounts,
  connecting,
  defaultEmail,
  werseeEmails,
  userName,
  onConnect,
  onSkip,
  onToggleTheme,
  onConnected,
  theme,
}: MailAccountSetupProps) => {
  const [started, setStarted] = useState(false);

  return (
    <main className="wm-setup-screen">
      <div className="wm-setup-ambient" aria-hidden="true"><i /><i /><i /></div>
      <header className="wm-setup-topbar">
        <a href="/" className="wm-setup-brand"><img src="/mail/icon.svg" alt="" /><span>Wersee <b>Mail</b></span></a>
        <div className="wm-setup-progress"><span className="is-done"><Check /></span><i /><span className={started ? 'is-active' : ''}>{started ? '2' : '1'}</span><i /><span>3</span></div>
        <button onClick={onToggleTheme} aria-label={`Use ${theme === 'dark' ? 'light' : 'dark'} appearance`}><span>{theme === 'dark' ? 'Light' : 'Dark'}</span><Sparkles /></button>
      </header>

      <section className={`wm-setup-shell ${started ? 'is-started' : ''}`}>
        <div className="wm-setup-cinema" aria-hidden="true">
          <span className="wm-cinema-grid" />
          <span className="wm-cinema-halo is-one" />
          <span className="wm-cinema-halo is-two" />
          <div className="wm-cinema-orbit is-outer"><i /></div>
          <div className="wm-cinema-orbit is-inner"><i /></div>
          <div className="wm-cinema-core"><img src="/mail/icon.svg" alt="" /><span /></div>
          <div className="wm-cinema-provider is-wersee"><ProviderMark provider="wersee" /><small>Wersee</small></div>
          <div className="wm-cinema-provider is-gmail"><ProviderMark provider="gmail" /><small>Gmail</small></div>
          <div className="wm-cinema-provider is-microsoft"><ProviderMark provider="microsoft" /><small>Outlook</small></div>
          <div className="wm-cinema-provider is-business"><ProviderMark provider="imap" /><small>Business</small></div>
          <div className="wm-cinema-message is-one"><span /><i /><i /></div>
          <div className="wm-cinema-message is-two"><span /><i /><i /></div>
          <div className="wm-cinema-scan" />
          <p><ShieldCheck /> Private connection layer</p>
        </div>

        <div className="wm-setup-content">
          {!started ? (
            <div className="wm-setup-intro">
              <p className="wm-setup-eyebrow"><Sparkles /> A calmer inbox starts here</p>
              <h1>Bring every conversation into focus.</h1>
              <p>Connect the inbox you already use. Wersee Mail keeps Gmail, Outlook and business mail together in one fluid, private workspace.</p>
              <div className="wm-setup-benefits">
                <span><Check /><b>Your folders and mail</b><small>Synced from the real provider</small></span>
                <span><Check /><b>AI only when you choose</b><small>Review every suggested reply</small></span>
                <span><Check /><b>One Wersee account</b><small>Pay links, invoices and DMs ready</small></span>
              </div>
              <button className="wm-setup-primary" onClick={() => setStarted(true)}><span>Set up my inbox</span><ArrowRight /></button>
              <button className="wm-setup-skip" onClick={onSkip}>I’ll connect an account later</button>
              <small className="wm-setup-welcome">Welcome, {userName}. This animation only appears during first setup.</small>
            </div>
          ) : (
            <div className="wm-setup-connect">
              <button className="wm-setup-back" onClick={() => setStarted(false)}><ArrowLeft /> Back</button>
              <p className="wm-setup-eyebrow"><Link2 /> Connect your first account</p>
              <h1>Choose where your mail lives.</h1>
              <p>Pick a provider and finish the secure connection. Nothing is imported until the provider approves it.</p>
              <MailProviderConnect
                accounts={accounts}
                connecting={connecting}
                defaultEmail={defaultEmail}
                werseeEmails={werseeEmails}
                onConnect={onConnect}
                onConnected={onConnected}
                variant="setup"
              />
              <button className="wm-setup-skip" onClick={onSkip}>Skip for now — open empty inbox</button>
            </div>
          )}
        </div>
      </section>

      <footer className="wm-setup-footer"><span><LockKeyhole /> Provider credentials stay out of the browser after connection.</span><span>Step {started ? '2' : '1'} of 3</span></footer>
    </main>
  );
};
