import { FormEvent, useEffect, useState } from 'react';
import { ArrowLeft, LoaderCircle, Mail, ShieldCheck } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../lib/supabase';
import { beginWerseeMailOAuth, getMailOAuthRedirectUri, isWerseeMailOAuthConfigured } from './werseeOAuth';
import './mail.css';

export const MailAuthStart = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [working, setWorking] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const oauthConfigured = isWerseeMailOAuthConfigured();

  useEffect(() => {
    if (user) navigate('/app', { replace: true });
  }, [navigate, user]);

  const continueWithWersee = async () => {
    setWorking(true);
    setError(null);
    try {
      await beginWerseeMailOAuth();
    } catch (authError) {
      setError(authError instanceof Error ? authError.message : 'Wersee authorization could not start.');
      setWorking(false);
    }
  };

  const sendMagicLink = async (event: FormEvent) => {
    event.preventDefault();
    setWorking(true);
    setError(null);
    try {
      const { error: signInError } = await supabase.auth.signInWithOtp({
        email: email.trim(),
        options: { emailRedirectTo: getMailOAuthRedirectUri() },
      });
      if (signInError) throw signInError;
      setSent(true);
    } catch (authError) {
      setError(authError instanceof Error ? authError.message : 'The secure sign-in link could not be sent.');
    } finally {
      setWorking(false);
    }
  };

  return (
    <main className="wm-auth-shell">
      <section className="wm-auth-card" aria-labelledby="wm-auth-title">
        <Link to="/" className="wm-auth-back"><ArrowLeft /> Back</Link>
        <img src="/mail/icon.svg" alt="" />
        <span className="wm-auth-eyebrow"><ShieldCheck /> Secure first-party sign-in</span>
        <h1 id="wm-auth-title">Continue to Wersee Mail</h1>
        <p>Your inbox uses your Wersee identity. Mail access remains owner-scoped and is never shared with another app.</p>

        {oauthConfigured ? (
          <button className="wm-auth-primary" onClick={() => void continueWithWersee()} disabled={working}>
            {working ? <LoaderCircle className="wm-spin" /> : <img src="/mail/icon.svg" alt="" />}
            Continue with Wersee
          </button>
        ) : null}

        {oauthConfigured ? <div className="wm-auth-divider"><span>or use a secure link</span></div> : null}

        {sent ? (
          <div className="wm-auth-sent"><Mail /><div><b>Check your inbox</b><p>We sent a one-time sign-in link to {email}. You can close this tab after opening it.</p></div></div>
        ) : (
          <form onSubmit={sendMagicLink}>
            <label><span>Wersee account email</span><input type="email" required autoComplete="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@company.com" /></label>
            <button className="wm-auth-secondary" disabled={working || !email.trim()}>{working ? <LoaderCircle className="wm-spin" /> : <Mail />} Send secure sign-in link</button>
          </form>
        )}
        {error ? <div className="wm-auth-error" role="alert">{error}</div> : null}
        <small>By continuing, you agree to Wersee's <a href="https://www.wersee.com/terms">Terms</a> and <a href="https://www.wersee.com/privacy-policy">Privacy Policy</a>.</small>
      </section>
    </main>
  );
};
