import { supabase, supabaseUrl } from '../../lib/supabase';

const clientId = String(import.meta.env.VITE_WERSEE_MAIL_OAUTH_CLIENT_ID || '').trim();
const transactionKey = 'wersee:mail:oauth-transaction';

interface OAuthTransaction {
  state: string;
  verifier: string;
  redirectUri: string;
  createdAt: number;
}

const base64Url = (bytes: Uint8Array) => {
  let value = '';
  bytes.forEach((byte) => { value += String.fromCharCode(byte); });
  return btoa(value).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
};

const randomValue = (length = 48) => base64Url(crypto.getRandomValues(new Uint8Array(length)));

const challengeFor = async (verifier: string) => {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier));
  return base64Url(new Uint8Array(digest));
};

export const isWerseeMailOAuthConfigured = () => Boolean(clientId);

export const getMailOAuthRedirectUri = () => {
  if (typeof window === 'undefined') return 'https://email.wersee.com/auth/callback';
  return `${window.location.origin}/auth/callback`;
};

export const beginWerseeMailOAuth = async () => {
  if (!clientId) {
    throw new Error('Wersee Mail OAuth has not been registered for this origin yet.');
  }

  const verifier = randomValue();
  const state = randomValue(32);
  const redirectUri = getMailOAuthRedirectUri();
  const transaction: OAuthTransaction = { state, verifier, redirectUri, createdAt: Date.now() };
  sessionStorage.setItem(transactionKey, JSON.stringify(transaction));

  const authorizationUrl = new URL(`${supabaseUrl.replace(/\/$/, '')}/auth/v1/oauth/authorize`);
  authorizationUrl.searchParams.set('client_id', clientId);
  authorizationUrl.searchParams.set('redirect_uri', redirectUri);
  authorizationUrl.searchParams.set('response_type', 'code');
  authorizationUrl.searchParams.set('scope', 'openid email profile');
  authorizationUrl.searchParams.set('state', state);
  authorizationUrl.searchParams.set('code_challenge', await challengeFor(verifier));
  authorizationUrl.searchParams.set('code_challenge_method', 'S256');
  window.location.assign(authorizationUrl.toString());
};

export const completeWerseeMailOAuth = async (params: URLSearchParams) => {
  const raw = sessionStorage.getItem(transactionKey);
  sessionStorage.removeItem(transactionKey);
  if (!raw) throw new Error('The sign-in request expired. Please try again.');

  const transaction = JSON.parse(raw) as OAuthTransaction;
  if (Date.now() - transaction.createdAt > 10 * 60 * 1000) {
    throw new Error('The sign-in request expired. Please try again.');
  }
  if (!params.get('code') || params.get('state') !== transaction.state) {
    throw new Error('We could not verify this sign-in request.');
  }

  const tokenResponse = await fetch(`${supabaseUrl.replace(/\/$/, '')}/auth/v1/oauth/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      code: params.get('code') || '',
      client_id: clientId,
      redirect_uri: transaction.redirectUri,
      code_verifier: transaction.verifier,
    }),
  });
  const tokens = await tokenResponse.json().catch(() => ({})) as {
    access_token?: string;
    refresh_token?: string;
    error?: string;
    error_description?: string;
  };
  if (!tokenResponse.ok || !tokens.access_token || !tokens.refresh_token) {
    throw new Error(tokens.error_description || tokens.error || 'Wersee sign-in failed.');
  }

  const { error } = await supabase.auth.setSession({
    access_token: tokens.access_token,
    refresh_token: tokens.refresh_token,
  });
  if (error) throw error;
};
