import type { ConnectedMailAccount, MailBootstrap } from './types';

const connectedStatuses = new Set(['active', 'connected']);

export const isConnectedMailAccount = (account: ConnectedMailAccount) =>
  connectedStatuses.has(account.status.toLowerCase());

export const shouldShowMailAccountSetup = (
  bootstrap: MailBootstrap | null,
  loading: boolean,
  dismissed: boolean,
) => Boolean(
  bootstrap
  && !loading
  && !dismissed
  && !bootstrap.status.connectedAccounts
  && !bootstrap.accounts.some(isConnectedMailAccount),
);
