import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { ArrowLeft, Clock3, LoaderCircle, LockKeyhole, Mail, UsersRound } from 'lucide-react';
import { useParams } from 'react-router-dom';
import { supabase } from '../../lib/supabase';

type SharedMessage = {
  id: string;
  subject: string;
  sender: string;
  recipients: string[];
  text_body: string;
  received_at: string;
  expires_at: string;
  team_name: string | null;
};

export const MailSharedMessagePage = () => {
  const { token = '' } = useParams();
  const [message, setMessage] = useState<SharedMessage | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    void (async () => {
      try {
        const { data } = await supabase.rpc('get_wersee_mail_share', { p_token: token }).maybeSingle();
        if (active) setMessage(data as SharedMessage | null);
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [token]);

  return <main className="wm-shared-page">
    <Helmet><title>{message?.subject || 'Shared email'} · Wersee Mail</title><meta name="robots" content="noindex,nofollow,noarchive" /><meta name="referrer" content="no-referrer" /></Helmet>
    <header><a href="/"><ArrowLeft /> Wersee Mail</a><span><LockKeyhole /> Private text copy</span></header>
    {loading ? <div className="wm-shared-state"><LoaderCircle className="wm-spin" /><p>Opening secure copy</p></div> : message ? <article className="wm-shared-card"><div className="wm-shared-icon"><Mail /></div><p className="wm-shared-eyebrow">Shared conversation</p><h1>{message.subject || '(No subject)'}</h1><div className="wm-shared-meta"><span><b>From</b>{message.sender}</span><span><b>To</b>{message.recipients.join(', ') || 'Private recipient'}</span><span><b>Received</b>{new Intl.DateTimeFormat(undefined, { dateStyle: 'long', timeStyle: 'short' }).format(new Date(message.received_at))}</span>{message.team_name ? <span><b>Team</b><UsersRound /> {message.team_name}</span> : null}</div><pre>{message.text_body || 'This email has no plain text content.'}</pre><footer><Clock3 /> This private link expires {new Intl.DateTimeFormat(undefined, { dateStyle: 'long' }).format(new Date(message.expires_at))}</footer></article> : <div className="wm-shared-state"><LockKeyhole /><h1>This private link is no longer available</h1><p>It may have expired or the owner may have revoked it.</p><a href="/">Go to Wersee Mail</a></div>}
  </main>;
};
