import { useEffect, useMemo, useState } from 'react';
import { Building2, Check, CircleDollarSign, Copy, Link2, LoaderCircle, Plus, Share2, UsersRound, X } from 'lucide-react';
import { toast } from 'sonner';
import { teamService, type Team } from '../../services/teamService';
import type { MailMessage } from './types';
import { createInvoiceFromMail, createMailShare, messageSenderEmail, messageSenderName } from './mailContextActions';

type Props = {
  message: MailMessage;
  userId: string;
  onClose: () => void;
  onInsertInvoice: (url: string) => void;
};

const slugFor = (value: string) => value.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);

export const MailContextPanel = ({ message, userId, onClose, onInsertInvoice }: Props) => {
  const [section, setSection] = useState<'invoice' | 'share'>('invoice');
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('EUR');
  const [customerName, setCustomerName] = useState(() => messageSenderName(message));
  const [customerEmail, setCustomerEmail] = useState(() => messageSenderEmail(message));
  const [itemTitle, setItemTitle] = useState(() => String(message.subject || 'Services from email conversation').slice(0, 220));
  const [memo, setMemo] = useState(() => `Based on our conversation about ${message.subject || 'your request'}`);
  const [working, setWorking] = useState(false);
  const [teams, setTeams] = useState<Team[]>([]);
  const [teamId, setTeamId] = useState('');
  const [newTeamName, setNewTeamName] = useState('');
  const [shareUrl, setShareUrl] = useState('');

  useEffect(() => {
    if (section !== 'share') return;
    void teamService.fetchTeams(userId).then((items) => setTeams(items as Team[])).catch((error) => toast.error(error instanceof Error ? error.message : 'Teams could not be loaded.'));
  }, [section, userId]);

  const amountNumber = Number(amount);
  const canCreateInvoice = useMemo(() => Number.isFinite(amountNumber) && amountNumber > 0 && /^\S+@\S+\.\S+$/.test(customerEmail), [amountNumber, customerEmail]);

  const createInvoice = async () => {
    if (!canCreateInvoice) return;
    setWorking(true);
    try {
      const result = await createInvoiceFromMail({ inboundId: message.id, customerEmail, customerName, itemTitle, memo, amount: amountNumber, currency });
      onInsertInvoice(result.paymentUrl);
      toast.success(`Invoice ${result.invoice.invoice_number} added to your reply for review.`);
      onClose();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Invoice could not be created.');
    } finally {
      setWorking(false);
    }
  };

  const createTeam = async () => {
    const name = newTeamName.trim();
    if (!name) return;
    setWorking(true);
    try {
      const team = await teamService.createTeam(userId, name, slugFor(name));
      setTeams((current) => [...current, team as Team]);
      setTeamId(team.id);
      setNewTeamName('');
      toast.success(`${name} is ready.`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Team could not be created.');
    } finally {
      setWorking(false);
    }
  };

  const share = async () => {
    setWorking(true);
    try {
      const result = await createMailShare({ ownerUserId: userId, message, teamId: teamId || null });
      const url = `${window.location.origin}/shared/${result.share_token}`;
      setShareUrl(url);
      await navigator.clipboard.writeText(url).catch(() => undefined);
      toast.success(teamId ? 'Secure team link copied.' : 'Private email link copied.');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Email could not be shared.');
    } finally {
      setWorking(false);
    }
  };

  return (
    <div className="wm-context-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <section className="wm-context-panel" role="dialog" aria-modal="true" aria-label="Conversation actions">
        <header><div><span><Building2 /></span><div><small>Conversation tools</small><h2>{message.subject || 'Email conversation'}</h2></div></div><button onClick={onClose} aria-label="Close"><X /></button></header>
        <nav><button className={section === 'invoice' ? 'is-active' : ''} onClick={() => setSection('invoice')}><CircleDollarSign /> Invoice</button><button className={section === 'share' ? 'is-active' : ''} onClick={() => setSection('share')}><Share2 /> Share</button></nav>

        {section === 'invoice' ? <div className="wm-context-content">
          <div className="wm-context-note"><CircleDollarSign /><span><b>Context filled, always reviewed by you</b><small>Wersee uses the sender and subject as a starting point. Nothing is sent until you send the reply.</small></span></div>
          <div className="wm-context-form is-two"><label><span>Customer</span><input value={customerName} onChange={(event) => setCustomerName(event.target.value)} maxLength={160} /></label><label><span>Email</span><input type="email" value={customerEmail} onChange={(event) => setCustomerEmail(event.target.value)} /></label></div>
          <label className="wm-context-field"><span>Invoice item</span><input value={itemTitle} onChange={(event) => setItemTitle(event.target.value)} maxLength={220} /></label>
          <div className="wm-context-form is-amount"><label><span>Amount</span><input inputMode="decimal" value={amount} onChange={(event) => setAmount(event.target.value.replace(',', '.'))} placeholder="0.00" /></label><label><span>Currency</span><select value={currency} onChange={(event) => setCurrency(event.target.value)}><option>EUR</option><option>USD</option><option>GBP</option></select></label></div>
          <label className="wm-context-field"><span>Memo</span><textarea value={memo} onChange={(event) => setMemo(event.target.value)} rows={3} maxLength={2000} /></label>
          <button className="wm-context-primary" onClick={() => void createInvoice()} disabled={!canCreateInvoice || working}>{working ? <LoaderCircle className="wm-spin" /> : <Plus />} Create invoice and add link</button>
        </div> : <div className="wm-context-content">
          <div className="wm-context-note"><UsersRound /><span><b>Share a safe text copy</b><small>Attachments, hidden email headers and remote content are never included.</small></span></div>
          <label className="wm-context-field"><span>Share with a team</span><select value={teamId} onChange={(event) => setTeamId(event.target.value)}><option value="">Anyone with the private link</option>{teams.map((team) => <option key={team.id} value={team.id}>{team.name}</option>)}</select></label>
          <div className="wm-create-team"><input value={newTeamName} onChange={(event) => setNewTeamName(event.target.value)} placeholder="New team name" maxLength={80} /><button onClick={() => void createTeam()} disabled={!newTeamName.trim() || working}><Plus /> Create team</button></div>
          {shareUrl ? <div className="wm-share-result"><Check /><span><b>Secure link ready</b><small>{shareUrl}</small></span><button onClick={() => void navigator.clipboard.writeText(shareUrl)} aria-label="Copy share link"><Copy /></button></div> : null}
          <button className="wm-context-primary" onClick={() => void share()} disabled={working}>{working ? <LoaderCircle className="wm-spin" /> : <Link2 />} {teamId ? 'Create team link' : 'Create private link'}</button>
        </div>}
      </section>
    </div>
  );
};
