import { supabase, supabasePublishableKey, supabaseUrl } from '../../lib/supabase';

export type MailApiAction =
  | 'bootstrap'
  | 'inbox'
  | 'message'
  | 'outbound'
  | 'message_action'
  | 'outbound_action'
  | 'register_attachment'
  | 'ai_request'
  | 'accounts'
  | 'account_connect'
  | 'account_authorize'
  | 'automations'
  | 'automation_create'
  | 'automation_toggle'
  | 'summaries'
  | 'summary_create';

const endpoint = `${supabaseUrl.replace(/\/$/, '')}/functions/v1/mail-bridge-app-api`;

export class MailApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = 'MailApiError';
  }
}

export const callMailApi = async <T>(
  action: MailApiAction,
  payload: Record<string, unknown> = {},
): Promise<T> => {
  const { data: { session }, error: sessionError } = await supabase.auth.getSession();
  if (sessionError || !session?.access_token) {
    throw new MailApiError('Your Wersee session has expired. Sign in again.', 401);
  }

  const response = await fetch(`${endpoint}?action=${encodeURIComponent(action)}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${session.access_token}`,
      apikey: supabasePublishableKey,
      'Content-Type': 'application/json',
      'X-Client-Info': 'wersee-mail-web/1.0',
    },
    body: JSON.stringify(payload),
    cache: 'no-store',
  });

  const result = await response.json().catch(() => ({ error: 'invalid_server_response' })) as T & {
    error?: string;
  };

  if (!response.ok || result?.error) {
    const message = result?.error
      ? String(result.error).replaceAll('_', ' ')
      : `Mail request failed (${response.status}).`;
    throw new MailApiError(message, response.status);
  }

  return result;
};

export const createIdempotencyKey = (scope: string) =>
  `wersee-mail:${scope}:${crypto.randomUUID()}`;
