import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { CheckCircle2, LoaderCircle, ShieldAlert } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { completeWerseeMailOAuth } from './werseeOAuth';
import './mail.css';

export const MailAuthCallback = () => {
  const navigate = useNavigate();
  const { refreshAuth } = useAuth();
  const [state, setState] = useState<'working' | 'success' | 'error'>('working');
  const [message, setMessage] = useState('Verifying your secure Wersee session…');

  useEffect(() => {
    let active = true;
    const finish = async () => {
      const params = new URLSearchParams(window.location.search);
      const providerConnected = params.get('connected') === 'true' || params.get('status') === 'connected';
      try {
        if (params.get('error')) throw new Error(params.get('error_description') || params.get('error') || 'Authorization was cancelled.');
        if (params.get('code') && params.get('state') && !providerConnected) {
          await completeWerseeMailOAuth(params);
          await refreshAuth();
          if (!active) return;
          setMessage('Signed in. Opening your private inbox…');
        } else {
          await refreshAuth();
          if (!active) return;
          setMessage(providerConnected ? 'Mailbox connected. Sync will start securely.' : 'Session restored. Opening Wersee Mail…');
        }
        setState('success');
        window.setTimeout(() => navigate('/app', { replace: true }), 550);
      } catch (callbackError) {
        if (!active) return;
        setState('error');
        setMessage(callbackError instanceof Error ? callbackError.message : 'Authorization could not be completed.');
      }
    };
    void finish();
    return () => { active = false; };
  }, [navigate, refreshAuth]);

  return (
    <main className="wm-callback-shell">
      <div className="wm-callback-card" role="status" aria-live="polite">
        <img src="/mail/icon.svg" alt="Wersee Mail" />
        {state === 'working' ? <LoaderCircle className="wm-spin" /> : state === 'success' ? <CheckCircle2 className="is-success" /> : <ShieldAlert className="is-error" />}
        <h1>{state === 'error' ? 'Could not finish signing in' : 'Wersee Mail'}</h1>
        <p>{message}</p>
        {state === 'error' ? <button onClick={() => navigate('/', { replace: true })}>Back to Wersee Mail</button> : null}
      </div>
    </main>
  );
};
